INSERT INTO `reviews` VALUES (1,1,2,'Tour rất tuyệt vời! Hướng dẫn viên nhiệt tình, lịch trình hợp lý. Vịnh Hạ Long thật sự đẹp như tranh vẽ. Sapa mát mẻ dễ chịu. Rất đáng đi!',5,NULL,1,'2025-01-20 15:30:00','2025-11-05 18:42:14','user','admin'),(2,2,3,'Chuyến đi rất ý nghĩa với gia đình. Đà Nẵng - Hội An - Huế đều có nét đẹp riêng. Đặc biệt ấn tượng với Cầu Vàng ở Bà Nà. Sẽ giới thiệu bạn bè!',5,NULL,1,'2025-01-25 10:00:00','2025-11-05 18:42:14','user','admin'),(3,3,8,'Phú Quốc đẹp lắm nhưng thời tiết hơi nóng. Biển xanh trong, đồ ăn ngon. Vinpearl Safari rất đáng đi. Resort sang trọng, phục vụ tốt.',4,NULL,1,'2025-02-02 14:20:00','2025-11-05 18:42:14','user','admin'),(4,1,10,'Tour tổ chức chuyên nghiệp. Khách sạn sạch sẽ, đồ ăn ngon miệng. HDV am hiểu, vui tính. Cảm ơn công ty đã mang đến chuyến đi đáng nhớ!',5,NULL,1,'2025-01-28 11:45:00','2025-11-05 18:42:14','user','admin'),(5,9,9,'Nha Trang vẫn đẹp như xưa! Tour 4 đảo vui lắm, được lặn biển ngắm san hô. Vinpearl Land có nhiều trò chơi hấp dẫn. Gia đình rất hài lòng!',5,NULL,1,'2025-02-05 16:00:00','2025-11-05 18:42:14','user','admin'),(6,5,5,'Nhật Bản thật sự là đất nước tuyệt vời! Núi Phú Sĩ hùng vĩ, Tokyo sầm uất, Kyoto cổ kính. HDV nhiệt tình, am hiểu văn hóa Nhật. Tour đáng giá!',5,NULL,1,'2025-02-10 09:30:00','2025-11-05 18:42:14','user','admin'),(8,2,4,'Cảm ơn công ty đã tổ chức tour tuyệt vời! Từ khách sạn, ăn uống đến hướng dẫn viên đều xuất sắc. Sẽ tiếp tục ủng hộ!',5,NULL,1,'2025-02-08 08:00:00','2025-11-05 18:42:14','user','admin'),(9,1,1,'',3,NULL,1,'2026-01-14 16:35:44','2026-01-16 20:12:04',NULL,'Thành'),(10,2,1,'',4,NULL,1,'2026-01-14 16:38:41','2026-01-14 16:38:41',NULL,NULL);
/*!40000 ALTER TABLE `reviews` ENABLE KEYS */;
UNLOCK TABLES;

