ULL,NULL),(61,9,'','','2025-12-05 16:31:18','2025-12-05 16:31:18',NULL,NULL),(62,1,'Hà Nội - Hạ Long','Khởi hành từ Hà Nội sáng sớm, đến Hạ Long, lên du thuyền ngắm Vịnh Hạ Long, thăm hang Sửng Sốt, tắm biển Titop','2026-01-07 13:59:43','2026-01-07 13:59:43',NULL,NULL),(63,1,'Hạ Long - Lào Cai','Về bến, di chuyển đến Lào Cai, nghỉ đêm tại khách sạn','2026-01-07 13:59:43','2026-01-07 13:59:43',NULL,NULL),(64,1,'Sapa - Fansipan','Chinh phục đỉnh Fansipan bằng cáp treo, thăm bản Cát Cát, chợ tình Sapa','2026-01-07 13:59:43','2026-01-07 13:59:43',NULL,NULL),(65,1,'Sapa - Hà Nội','Tự do mua sắm đặc sản Sapa, trở về Hà Nội','2026-01-07 13:59:43','2026-01-07 13:59:43',NULL,NULL),(66,13,'Ngày 1','<p>Đớp canh c&aacute; Quỳnh C&ocirc;i</p>\n<p><img src=\"http://localhost:8088/api/tinymce/images/canh-ca-quynh-coi-dac-san-thai-binh-vua-dac-san-e1610618037517-982x800_1764224013386_a5e1b2da.jpg\" alt=\"canh-ca-quynh-coi-dac-san-thai-binh-vua-dac-san-e1610618037517-982x800.jpg\" width=\"982\" height=\"800\"></p>','2026-01-13 17:17:13','2026-01-13 17:17:13',NULL,NULL),(67,13,'Ngày 2','<p>Đớp b&aacute;nh c&aacute;y</p>','2026-01-13 17:17:13','2026-01-13 17:17:13',NULL,NULL),(68,13,'Ngày 3','<p>Đớp đớp đớp</p>','2026-01-13 17:17:13','2026-01-13 17:17:13',NULL,NULL),(69,15,'','<ul>\n<li><strong>Cầu Bản X&aacute;:</strong>&nbsp;Cầu Bản X&atilde; l&agrave;&nbsp;<strong>cầu kết nối Quốc lộ 12 với khu t&aacute;i định cư</strong>. Cầu c&oacute; chiều d&agrave;i 670m, mặc cầu rộng 9m v&agrave; đ&aacute;p ứng hai l&agrave;n xe lưu th&ocirc;ng tr&ecirc;n cầu.&nbsp;<strong>D&ograve;ng nước ph&iacute;a dưới cầu trong xanh tạo n&ecirc;n khung cảnh rất đẹp</strong>, khi đứng tr&ecirc;n cầu c&aacute;c bạn sẽ được tận hưởng&nbsp;<strong>cảnh quan thi&ecirc;n nhi&ecirc;n của nơi đ&acirc;y v&ocirc; c&ugrave;ng đẹp.</strong></li>\n</ul>','2026-01-13 21:04:51','2026-01-13 21:04:51',NULL,NULL),(70,15,'','<ul>\n<li><strong>Cầu Hang T&ocirc;m:</strong>&nbsp;Cầu Hang T&ocirc;m&nbsp;<strong>nối phường S&ocirc;ng Đ&agrave; thuộc Mường Lay với x&atilde; L&ecirc; Lợi</strong>, tỉnh Điện Bi&ecirc;n thuộc huyện Nậm Nh&ugrave;n, tỉnh Lai Ch&acirc;u. Cầu Hang T&ocirc;m cũ được x&acirc;y dựng từ năm 1967, đ&acirc;y<strong>&nbsp;từng l&agrave; c&acirc;y cầu d&acirc;y văng lớn nhất Đ&ocirc;ng Dương l&uacute;c bấy giờ.</strong></li>\n</ul>','2026-01-13 21:04:51','2026-01-13 21:04:51',NULL,NULL),(71,16,'NGÀY 1 HÀ NỘI - HÀ GIANG - QUẢN BẠ - YÊN MINH ( ĂN TRƯA, TỐI)','<p><strong>05h30 - 06h00:</strong>&nbsp;Xe v&agrave; HDV đ&oacute;n Qu&yacute; kh&aacute;ch tại điểm hẹn khởi h&agrave;nh đi&nbsp;<strong>du lịch H&agrave; Giang</strong>&nbsp;- v&ugrave;ng đất c&oacute; ch&egrave; san, rượu mật ong v&agrave; thắng cố, xứ sở của đ&agrave;o phai, hoa l&ecirc;,hoa tam gi&aacute;c mạch, truyền thống v&agrave; n&aacute;o nhiệt trong buổi chợ phi&ecirc;n&hellip;Tr&ecirc;n đường đi, đo&agrave;n dừng ch&acirc;n ăn s&aacute;ng tự t&uacute;c tại ch&acirc;n đường cao tốc s&acirc;n bay Nội B&agrave;i.</p>\n<p><strong>11h30:</strong>&nbsp;Qu&yacute; kh&aacute;ch d&ugrave;ng cơm trưa tại nh&agrave; h&agrave;ng.</p>\n<p>Đo&agrave;n tiếp tục h&agrave;nh tr&igrave;nh đến&nbsp;<strong>cột mốc số O &ndash; Tp H&agrave; Giang</strong>,đo&agrave;n dừng ch&acirc;n chụp ảnh lưu niệm v&agrave; nghỉ ngơi trong gi&acirc;y l&aacute;t. Sau đ&oacute; đo&agrave;n khởi h&agrave;nh đi Quản Bạ, mỗi du kh&aacute;ch đến đ&acirc;y đều c&oacute; dịp chi&ecirc;m ngưỡng&nbsp;<strong>N&uacute;i Đ&ocirc;i C&ocirc; Ti&ecirc;n</strong>&nbsp;- &ldquo;t&aacute;c phẩm nghệ thuật&rdquo; của tạo ho&aacute; ban tặng cho v&ugrave;ng đất n&agrave;y, nơi m&agrave; bạn c&oacute; thể ngắm to&agrave;n bộ khung cảnh thị trấn Tam Sơn trong l&ograve;ng ống k&iacute;nh. Tiếp tục khởi h&agrave;nh đi Y&ecirc;n Minh.</p>\n<p><strong>18h00:</strong>&nbsp;Đo&agrave;n đến thị trấn&nbsp;<strong>Y&ecirc;n Minh</strong>, ăn tối tại nh&agrave; h&agrave;ng v&agrave; nhận ph&ograve;ng kh&aacute;ch sạn nghỉ ngơi. Tự do kh&aacute;m ph&aacute; thị trấn về đ&ecirc;m với c&aacute;c m&oacute;n ăn như: ch&aacute;o ấu tẩu, phở Tr&aacute;ng K&igrave;m, s&ocirc;i ngũ sắc, b&aacute;nh cuốn trứng chấm nước xương hầm, thắng cố, m&egrave;n m&eacute;n, rượu ng&ocirc; l&agrave; những m&oacute;n ăn n&ecirc;n thử một lần ở H&agrave; Giang...</p>','2026-01-16 08:26:30','2026-01-16 08:26:30',NULL,NULL),(72,16,'NGÀY 2 YÊN MINH - LŨNG CÚ - ĐỒNG VĂN ( ĂN SÁNG, TRƯA, TỐI)','<p><strong>06h00-06h30:</strong>&nbsp; Qu&yacute; kh&aacute;ch thức dậy ăn s&aacute;ng v&agrave; l&agrave;m thủ tục trả ph&ograve;ng.</p>\n<p><strong>07h30 &ndash; 08h00</strong>: Xe v&agrave; Hướng dẫn vi&ecirc;n đưa Qu&yacute; kh&aacute;ch đi&nbsp;<strong>Cao nguy&ecirc;n Đ&aacute;&nbsp;Đồng Văn</strong>&nbsp;- l&agrave; một cao nguy&ecirc;n đ&aacute; trải rộng tr&ecirc;n bốn huyện Quản Bạ, Y&ecirc;n Minh, Đồng Văn, M&egrave;o Vạc. Q&uacute;y kh&aacute;ch thỏa sức ngắm nh&igrave;n, v&agrave; chụp ảnh tr&ecirc;n những c&aacute;nh đồng hoa đua nhau khoe sắc, c&ugrave;ng nhau trải nghiệm những kh&uacute;c cua đẹp nhất tr&ecirc;n cung đường &ldquo; Hạnh Ph&uacute;c.&rdquo; Như kh&uacute;c Ch&iacute;n quanh, cung đường chữ M cung chữ U hay W&hellip;.</p>\n<p><strong>Tham quan b&atilde;i đ&aacute; Mặt Trăng</strong>&nbsp;- Kh&ocirc;ng gian của đ&aacute;, với m&agrave;u sắc v&agrave; h&igrave;nh khối độc lạ của những địa h&igrave;nh n&uacute;i đ&aacute; v&ocirc;i, tạo n&ecirc;n n&eacute;t đặc biệt của những b&atilde;i đ&aacute; m&agrave; người ta gọi l&agrave; b&atilde;i đ&aacute; Mặt trăng tr&ecirc;n cao nguy&ecirc;n đ&aacute;&nbsp;<a href=\"https://zingnews.vn/tieu-diem/ha-giang.html\">H&agrave; Giang</a></p>\n<p>Qu&yacute; kh&aacute;ch gh&eacute; thăm&nbsp;<strong>dinh nh&agrave; họ Vương (dinh vua M&egrave;o)</strong>&nbsp;với nhiều kiến tr&uacute;c độc đ&aacute;o v&agrave; những c&acirc;u chuyện đặc sắc.</p>\n<p><strong>Qu&yacute; kh&aacute;ch đến Lũng C&uacute;</strong>&nbsp;- Nơi địa đầu Tổ Quốc, hay c&ograve;n được mi&ecirc;u tả l&agrave;: &ldquo;Nơi c&uacute;i mặt s&aacute;t đất, ngẩng mặt đụng trời&rdquo;. Qu&yacute; kh&aacute;ch thăm quan Cột cờ Tổ Quốc v&agrave; chụp h&igrave;nh lưu niệm.</p>\n<p>Từ cột cờ Lũng C&uacute;, Qu&yacute; kh&aacute;ch c&oacute; thể ngắm phong cảnh ruộng bậc thang đẹp mắt xen kẽ những nh&agrave; tr&igrave;nh tường của d&acirc;n tộc L&ocirc; L&ocirc; trong bản S&eacute;o Lủng b&ecirc;n dưới.</p>\n<p><strong>Q&uacute;y kh&aacute;ch sẽ c&oacute; dịp được tham quan bản L&ocirc; L&ocirc;</strong>&nbsp;Với đặc điểm</p>\n<p>90% d&acirc;n cư l&agrave; đồng b&agrave;o L&ocirc; l&ocirc;, nơi đ&acirc;y vẫn c&ograve;n lưu giữ được vẹn nguy&ecirc;n những n&eacute;t văn h&oacute;a của nh&oacute;m người n&agrave;y. &nbsp;Ng&ocirc;i l&agrave;ng đẹp như những ng&ocirc;i l&agrave;ng trong c&aacute;c c&acirc;u truyện cổ t&iacute;ch ng&agrave;y xưa ch&uacute;ng ta được nghe.</p>\n<p><strong>12h00</strong>: Qu&yacute; kh&aacute;ch ăn trưa tại nh&agrave; h&agrave;ng.</p>\n<p><strong>Chiều:&nbsp;</strong>Xe đưa đo&agrave;n đi tham quan v&agrave; chinh phục đ&egrave;o&nbsp;<strong>M&atilde; P&igrave; L&egrave;ng, một trong &ldquo;Tứ Đại Đỉnh Đ&egrave;o&rdquo;</strong>&nbsp;nổi tiếng nhất của Việt Nam, với độ cao 2000m so với mực nước biển với những dốc, kh&uacute;c cua tay &aacute;o quanh co..&nbsp;</p>\n<p>Đo&agrave;n&nbsp;<strong>du thuyền tr&ecirc;n s&ocirc;ng Nho Quế</strong>, kh&aacute;m ph&aacute; Hẻm Tu sản đẹp như tranh vẽ v&agrave; ngắm to&agrave;n cảnh TP H&agrave; Giang từ tr&ecirc;n cao đẹp như bức tranh thủy mặc tại Việt Nam m&agrave; kh&ocirc;ng một nơi n&agrave;o c&oacute; được.</p>\n<p><strong>Tối:</strong> Qu&yacute; kh&aacute;ch d&ugrave;ng bữa tối tại nh&agrave; h&agrave;ng.</p>','2026-01-16 08:26:30','2026-01-16 08:26:30',NULL,NULL),(73,17,'','','2026-01-16 08:31:01','2026-01-16 08:31:01',NULL,NULL),(74,17,'','','2026-01-16 08:31:01','2026-01-16 08:31:01',NULL,NULL),(83,20,'lich trinh','<h3>Đặc trưng kh&iacute; hậu H&agrave; Nam</h3>\n<p class=\"MsoNormal\">Kh&iacute; hậu H&agrave; Nam mang đặc điểm của kh&iacute; hậu nhiệt đới gi&oacute; m&ugrave;a. Nhiệt độ trung b&igrave;nh năm rơi v&agrave;o khoảng 23 - 24 độ C. Trong năm c&oacute; 8 đến 9 th&aacute;ng c&oacute; nhiệt độ trung b&igrave;nh tr&ecirc;n 20 độ C (trong đ&oacute; c&oacute; 5 th&aacute;ng nhiệt độ trung b&igrave;nh tr&ecirc;n 25 độ C). Chỉ c&oacute; 3 th&aacute;ng c&oacute; nhiệt độ trung b&igrave;nh dưới 20 độ C, nhưng kh&ocirc;ng c&oacute; th&aacute;ng n&agrave;o nhiệt độ dưới 16 độ C. Lượng mưa trung b&igrave;nh năm của H&agrave; Nam rơi v&agrave;o khoảng 1900mm. Độ ẩm trung b&igrave;nh khoảng 85%.</p>','2026-01-16 10:22:46','2026-01-16 10:22:46','Thành','Thành'),(84,20,'','<h3>Thời gian th&iacute;ch hợp để du lịch H&agrave; Nam</h3>\n<p class=\"MsoNormal\">Nhờ đặc điểm kh&iacute; hậu nhiệt đới gi&oacute; m&ugrave;a đặc trưng, H&agrave; Nam v&agrave;o mỗi m&ugrave;a đều mang trong m&igrave;nh những n&eacute;t đẹp ri&ecirc;ng v&agrave; quyến rũ. Do đ&oacute;, bạn c&oacute; thể đến gh&eacute; thăm H&agrave; Nam bất cứ l&uacute;c n&agrave;o. Tuy nhi&ecirc;n, do sự đa dạng của c&aacute;c hoạt động vui chơi giải tr&iacute; cũng như c&aacute;c lễ hội trong m&ugrave;a xu&acirc;n, n&ecirc;n đến H&agrave; Nam v&agrave;o thời điểm n&agrave;y l&agrave; l&yacute; tưởng nhất.</p>','2026-01-16 10:22:46','2026-01-16 10:22:46','Thành','Thành');
