 chốn bồng lai ti&ecirc;n cảnh, t&acirc;m linh nổi tiếng tại đảo Ngọc</li>\n<li>Nh&agrave; th&ugrave;ng nước mắc, Nh&agrave; t&ugrave; Ph&uacute; Quốc, Suối Tranh (con suối đẹp nhất Ph&uacute; Quốc)</li>\n<li>Dinh Cậu, chợ đ&ecirc;m Dinh Cậu.</li>\n</ul>','Mang theo kem chống nắng, đồ bơi','https://maps.google.com/?q=phu+quoc',3,30,20,10,'[0.052581344,0.06295273,1.7627461E-4,-0.049883228,0.053942904,-0.014539173,-0.014884597,-0.0051772054,-0.016892318,-0.029029999,0.023192763,0.05184248,0.08496724,0.012910534,0.020155175,0.00805521,0.03438734,0.018473625,-0.08990635,-0.03656752,-0.012190103,0.056456223,0.023331026,0.043540135,-0.0038336103,-0.048821226,-0.044328175,0.044827152,0.02498125,-0.074171,0.007259349,0.043204095,-0.044745453,0.034478404,-0.0017112241,0.039170876,0.02178001,-0.031075079,0.016468586,-0.063348174,-0.032780416,-0.036283523,0.057880335,0.0020765115,-0.04352372,-0.05218061,-0.045581024,0.0044498066,-0.018065797,-0.0021410629,0.024606032,0.01709624,-0.029318275,0.07964262,-0.057152767,0.012282156,-0.024247354,-0.07279805,0.0129661765,-0.038751148,0.009375506,-0.011460899,-0.029905966,0.004973898,-0.0025290812,-0.033020012,0.0010961142,0.0054007624,-0.022495912,-0.017548073,-0.041364223,0.07092742,-0.026466152,0.025188398,0.06741837,-0.056175057,0.004055407,0.028613508,0.0961417,0.0560978,-0.031044044,0.0016074044,0.018695911,0.0630545,0.008726587,-0.006261938,-0.0016991082,-0.026942667,-0.037305996,-0.033334944,0.033746816,-0.019641917,-0.011347568,-0.07175335,0.054585367,-0.01715575,-0.04894233,-0.09714332,0.039939217,0.024302006,-0.0033456387,-0.025785593,-0.0054480713,-0.033981603,0.010565787,-0.0015603884,-0.020911826,-0.010843515,-0.0476813,0.030535663,-5.5578625E-4,-0.058844533,0.040885165,-0.029140376,-0.013746415,-0.017049458,-0.027381914,0.021475008,-0.053961433,-0.0375736,0.03713507,0.027417606,-0.034877542,0.041233853,0.012273179,0.024632927,-0.042349283,-0.053413972,-0.011918931,-0.05701285,-0.007046899,-0.039188348,-0.03488896,-0.0219