859,0.032192152,-0.018612877,-0.019694453,0.016011007,-0.009508942,-0.0065328768,0.007179765,-0.0073278113,-0.050637346,0.016243111,-0.021323822,0.067494996,0.04318286,-0.070057824,0.020256579,-0.03205836,0.013858347,0.02481859,-0.011450453,0.005487674,-0.012260998,0.016403737,-0.038280316,-0.04893303,0.055656727,0.02531827,-0.03752933,-0.032173157,0.025830844,0.0686942,-0.0038085557,-0.044078704,0.021263607,-0.016130483,0.07574146,0.010617464,-0.028887387,-0.07704477,0.004082878,-0.05280565,-0.015390584,0.025826968,0.013853295,-0.0648548,-0.025878688,0.04871818,2.5585984E-4,-0.047028102,-0.048045326,-0.017289892,-0.012364908,0.022255275,-0.022435032,-0.009430397,-0.060299058,-0.07851338,0.020604879,-0.00488989,-0.05652498,0.048299998,0.0065262066,-0.028793197,0.0023508403,-0.006973587,0.0366604,-0.0132619785,0.0800345,-0.021047767,0.04154393,-0.05792087,-0.0068078414,0.027871147,-0.0073813107]',1,3,'2025-11-24 17:55:44','2026-01-14 00:17:14',NULL,NULL),(14,'Tour Sa Pa','6bcfb88a-ca54-4667-8efe-96ece3d1be3d_sapa-2.jpg',1000000,700000,500000,'Ô tô',NULL,'<h3 class=\"ryydwwjtlwr\" style=\"text-align: center;\">Sa Pa m&ugrave;a n&agrave;o đẹp</h3>\n<p>Sa Pa c&oacute; kh&iacute; hậu m&aacute;t mẻ n&ecirc;n ph&ugrave; hợp với những chuyến du lịch quanh năm. Bạn chỉ cần tr&aacute;nh m&ugrave;a mưa b&atilde;o từ th&aacute;ng 6 đến đầu th&aacute;ng 8, bởi thời tiết cực đoan c&oacute; thể g&acirc;y lũ ống, lũ qu&eacute;t, sạt lở...</p>\n<p>Từ th&aacute;ng 2 đến th&aacute;ng 5, m&ugrave;a xu&acirc;n Sa Pa rực rỡ với trăm hoa khoe sắc như mai anh đ&agrave;o, đ&agrave;o, mận... M&ugrave;a h&egrave; từ th&aacute;ng 6 đến th&aacute;ng 8 l&agrave; thời điểm kh&aacute;ch du lịch đến Sa Pa để trốn n&oacute;ng, ngắm những thửa ruộng bậc thang xanh m&aacute;t.</p>\n<p>M&ugrave;a thu k&eacute;o d&agrave;i từ th&aacute;ng 9 đến th&aacute;ng 11, Sa Pa quyến rũ trong m&agrave;u v&agrave;ng &oacute;ng ả của l&uacute;a ch&iacute;n v&agrave; trời dần trở lạnh. M&ugrave;a đ&ocirc;ng đến từ th&aacute;ng 12 đến th&aacute;ng 2 năm sau, nếu may mắn bạn c&oacute; thể \"săn\" tuyết, băng gi&aacute; tr&ecirc;n những đỉnh n&uacute;i.</p>\n<p><img src=\"https://i1-dulich.vnecdn.net/2022/05/10/Sa-Pa-mai-anh-dao-8046-1650277-6665-2702-1652148656.jpg?w=0&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=Ea8Gc-UBmPPZl9tWBE5LWA\" alt=\"Sa-Pa-mai-anh-dao-8046-1650277614.jpg\"></p>\n<h3 class=\"hgdsr8hm8s6\" style=\"text-align: center;\">Di chuyển</h3>\n<p>Bạn c&oacute; thể đặt xe limousine H&agrave; Nội - Sa Pa hoặc xe kh&aacute;ch từ bến Mỹ Đ&igrave;nh với gi&aacute; 230.000 - 350.000 đồng một người, t&ugrave;y hạng ghế. Thời gian di chuyển khoảng 5 - 6 tiếng.</p>\n<p>Nếu đi t&agrave;u hỏa chạy, bạn chọn chuyến H&agrave; Nội - L&agrave;o Cai, sau khoảng 7 - 9 tiếng di chuyển phải đ&oacute;n tiếp xe bus hoặc bắt taxi l&ecirc;n trung t&acirc;m Sa Pa. Gi&aacute; v&eacute; t&agrave;u từ 160.000 đến 800.000 đồng t&ugrave;y hạng ghế v&agrave; loại t&agrave;u.</p>\n<p>Nếu tự l&aacute;i &ocirc;t&ocirc;, bạn đi cao tốc Nội B&agrave;i - L&agrave;o Cai, tiếp đ&oacute; rẽ sang đường 4D để l&ecirc;n Sa Pa. Đường dễ đi, nhưng bạn cần ch&uacute; &yacute; quan s&aacute;t biển b&aacute;o, chạy đ&uacute;ng tốc độ. V&agrave;o những dịp trời mưa lạnh, nhiều sương m&ugrave; v&agrave; đường trơn, bạn n&ecirc;n kiểm tra kỹ lốp xe, hệ thống phanh, đ&egrave;n... trước khi khởi h&agrave;nh. Thời gian chạy xe khoảng 5 - 6 tiếng. H&atilde;y khởi h&agrave;nh từ H&agrave; Nội muộn nhất khoảng 12h30, để khi đến đ&egrave;o l&ecirc;n Sa Pa, trời kh&ocirc;ng qu&aacute; tối.</p>\n<p><img src=\"https://i1-dulich.vnecdn.net/2022/05/10/xe-may-Sa-Pa-4073-1650277614-4473-1652148659.jpg?w=0&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=QB5igya8MlPBV2vwjZNgHA\"></p>',NULL,NULL,4,4,3,5,'[0.032884747,0.06467407,-0.027059715,-0.038136702,0.05897408,0.010165294,-0.03169162,-0.02023107,0.010237978,-0.0048115756,-0.0045486824,0.07281314,0.07525653,0.0050619747,-0.0058946013,0.010735194,-0.008022915,0.046412528,-0.07