1015,0.008924143,0.06583139,0.046625268,-0.055740036,0.049645495,-0.036442146,0.043874785,0.03149885,-0.013663169,0.030203972,0.0012031124,0.03019164,-0.045261055,-0.04326602,0.06093617,0.06331148,-0.026575867,0.003882028,0.02909397,0.07466304,-0.010306021,-0.029831618,0.0023375303,-0.019642545,0.09289296,0.017954294,-0.006669309,-0.07795631,0.0063056964,-0.04558118,-0.004158145,0.013910387,0.0043787546,-0.055604283,-0.033371616,0.059646197,0.0039239884,-0.024790885,-0.0412868,-0.022716919,0.0047408114,0.02632613,-0.014960918,-0.016475199,-0.06464614,-0.08127143,0.008098442,-0.00555424,-0.052564144,0.052071918,0.026255002,-0.027653133,0.013516871,8.440284E-4,0.026843289,-0.021731678,0.088765144,-0.020169605,0.041524015,-0.057056177,0.012125312,0.0018418767,0.015464189]',1,3,'2026-01-14 04:04:51','2026-01-15 19:50:27',NULL,NULL),(16,'Tour Hà Giang','6b79d90e-33df-44e2-a516-2be0cb877286_tour-ha-giang-3n2d-c.jpg',5000000,4000000,2000000,'Xe khách',NULL,'<p>H&agrave; Giang l&agrave; tỉnh địa đầu của Tổ quốc, ph&iacute;a Đ&ocirc;ng gi&aacute;p tỉnh Cao Bằng, ph&iacute;a T&acirc;y gi&aacute;p tỉnh Y&ecirc;n B&aacute;i v&agrave; L&agrave;o Cai, ph&iacute;a Nam gi&aacute;p tỉnh Tuy&ecirc;n Quang, ph&iacute;a Bắc gi&aacute;p Trung Quốc. C&aacute;c cung đường H&agrave; Giang quanh co, cheo leo vốn đầy th&aacute;ch thức cho người l&aacute;i xe. Thế nhưng khi bạn ph&oacute;ng tầm mắt xung quanh, căng thẳng nhường lại chỗ cho cảm gi&aacute;c thư th&aacute;i khi chi&ecirc;m ngưỡng vẻ đẹp cao nguy&ecirc;n.</p>\n<div class=\"section-inner inset-column\">\n<p>L&agrave; tỉnh miền n&uacute;i cao n&ecirc;n kh&iacute; hậu ở H&agrave; Giang lạnh r&otilde; rệt so với v&ugrave;ng thấp v&agrave; trung du kế cận. Nhiệt độ trung b&igrave;nh năm khoảng 21-23 độ C. N&eacute;t nổi bật của kh&iacute; hậu l&agrave; độ ẩm cao trong năm, mưa nhiều v&agrave; k&eacute;o d&agrave;i.</p>\n</div>\n<div class=\"section-inner inset-column\">\n<p>Bạn c&oacute; thể du lịch H&agrave; Giang v&agrave;o bất kỳ m&ugrave;a n&agrave;o trong năm. Người ta thường đến H&agrave; Giang v&agrave;o m&ugrave;a thu l&uacute;a ch&iacute;n v&agrave;ng. Thời gian đẹp nhất l&agrave; th&aacute;ng 10, 11 v&agrave; 12, khi hoa tam gi&aacute;c mạch hay những c&aacute;nh đồng cải khoe sắc. C&ograve;n m&ugrave;a xu&acirc;n, hoa mơ, hoa mận nở trắng rừng khiến bạn như đang bồng bềnh tr&ecirc;n m&acirc;y.</p>\n<p>Th&aacute;ng 5, những thửa ruộng lấp lo&aacute;ng m&ugrave;a nước đổ. Th&aacute;ng 6 v&agrave; th&aacute;ng 7, nhiều người bỏ lỡ H&agrave; Giang v&igrave; những cơn mưa h&egrave; r&eacute;o rắt bất chợt. Nhưng cũng nhờ sự ẩm ướt n&agrave;y, n&uacute;i rừng nơi đ&acirc;y lại kho&aacute;c l&ecirc;n m&igrave;nh một m&agrave;u xanh mướt say đắm l&ograve;ng người.</p>\n</div>',NULL,NULL,5,40,40,19,'[0.04062184,0.05438498,-0.021895368,-0.031349186,0.03749668,-0.017701842,-0.01997857,-0.022039266,-0.026434284,-0.007943696,-4.9099204E-4,0.066607535,0.054806225,-0.018332817,0.031741314,0.0050230236,0.028928176,-0.004227255,-0.07069713,-0.019480448,-0.003549968,-0.013428831,0.019654332,-0.012053993,0.024780098,-0.026753426,-0.064583145,0.03578794,0.003620113,-0.10285842,0.03012267,0.03433709,-0.051128894,0.065546304,0.015854975,0.043355316,0.028732028,-0.002453987,0.031630605,-0.072694816,-0.009767724,0.011585282,0.063441604,0.051930293,-0.026106203,-0.09691078,0.03498576,0.02360158,-0.040993027,0.021821497,0.014962516,0.018702975,0.0011441836,0.05663293,-0.026742484,0.036852825,-0.0054344414,-0.029007437,0.026763622,0.011822379,0.04347405,-0.0507221,-0.016453063,-0.022235837,-0.03545324,-0.024728566,-0.0400455,-0.021426804,-0.023836121,-0.01829104,-0.044047166,0.033170734,-0.033945736,0.04666802,0.0635589,-0.05088359,-0.027458835,0.014809093,0.066214204,0.025656097,-0.040828943,0.0034597851,0.027958563,0.044960134,-0.022238083,0.0021519852,0.024190674,-0.04056224,-0.039965067,-0.02360345,0.021338306,0.0060868817,-0.030276293,-0.057422694,0.07564991,-0.047971196,-0.036490906,-0.123408176,0.0435143