.049108163,-0.06504932,-0.06485312,0.0135157695,0.017816428,-0.019422557,0.058784872,-0.0119821625,-0.055814307,-0.0152886575,0.0065602614,0.039877668,-0.022256354,0.07677313,-0.008112546,0.05280049,-0.04157129,-0.0239857,0.037688468,-0.019087236]',1,3,'2026-01-16 15:26:30','2026-01-16 15:26:31',NULL,NULL),(17,'Tour Quảng Bình','e7cdbadc-6296-4a3b-b415-33ba8e86b1a9_camnhi-181620101619-quang-binh-5.jpg',5000000,4000000,3995599,'Ô tô',NULL,'<h3>Kh&aacute;m Ph&aacute; Những Điều Th&uacute; Vị Về Quảng B&igrave;nh</h3>\n<p>Quảng B&igrave;nh, một tỉnh ven biển miền Trung Việt Nam, nổi bật với vẻ đẹp tự nhi&ecirc;n v&agrave; di sản văn h&oacute;a phong ph&uacute;. Nơi đ&acirc;y l&agrave; qu&ecirc; hương của nhiều thắng cảnh nổi tiếng như&nbsp;<strong>hang Sơn Đo&ograve;ng</strong>, hang động lớn nhất thế giới, v&agrave;&nbsp;<strong>Vườn quốc gia Phong Nha &ndash; Kẻ B&agrave;ng</strong>, được UNESCO c&ocirc;ng nhận l&agrave; di sản thi&ecirc;n nhi&ecirc;n thế giới. H&atilde;y c&ugrave;ng kh&aacute;m ph&aacute; những điều th&uacute; vị v&agrave; độc đ&aacute;o m&agrave; Quảng B&igrave;nh mang lại, từ những cảnh đẹp kỳ vĩ đến những c&acirc;u chuyện lịch sử hấp dẫn.</p>\n<p>Kh&ocirc;ng chỉ dừng lại ở những hang động h&ugrave;ng vĩ, Quảng B&igrave;nh c&ograve;n sở hữu b&atilde;i biển Nhật Lệ tuyệt đẹp với c&aacute;t trắng mịn v&agrave; nước biển trong xanh. Du kh&aacute;ch c&oacute; thể thả m&igrave;nh v&agrave;o l&agrave;n s&oacute;ng m&aacute;t lạnh, tham gia c&aacute;c hoạt động thể thao dưới nước như lướt s&oacute;ng hay ch&egrave;o thuyền kayak. Đặc biệt, kh&ocirc;ng thể kh&ocirc;ng nhắc đến&nbsp;<strong>B&agrave;u Tr&oacute;</strong>, một trong những điểm đến nổi tiếng với cảnh quan thi&ecirc;n nhi&ecirc;n hoang sơ v&agrave; b&igrave;nh y&ecirc;n, nơi l&yacute; tưởng để thư gi&atilde;n v&agrave; tận hưởng kh&ocirc;ng kh&iacute; trong l&agrave;nh.</p>\n<p>Đến Quảng B&igrave;nh, bạn sẽ c&oacute; cơ hội t&igrave;m hiểu về văn h&oacute;a v&agrave; lịch sử đa dạng của v&ugrave;ng đất n&agrave;y. Những di t&iacute;ch lịch sử như&nbsp;<strong>Tour du lịch L&ecirc; Khang</strong> kh&ocirc;ng chỉ mang lại kiến thức về qu&aacute; khứ m&agrave; c&ograve;n l&agrave; nơi để bạn cảm nhận được sự ph&aacute;t triển của mảnh đất n&agrave;y qua c&aacute;c thời kỳ. Những c&acirc;u chuyện về người d&acirc;n nơi đ&acirc;y, phong tục tập qu&aacute;n v&agrave; c&aacute;c lễ hội truyền thống sẽ khiến bạn th&ecirc;m y&ecirc;u mến v&ugrave;ng đất n&agrave;y.</p>',NULL,NULL,3,36,26,74,'[0.030205375,0.03502245,-0.020092564,-0.036771465,0.04847551,-0.02137871,-0.0174128,-0.042145353,-0.001902458,-0.018997364,0.006551439,0.048486345,0.06573766,-0.0023109256,0.026392158,-0.01758554,0.03312291,0.031405482,-0.09412006,-0.03801895,0.026423687,0.016357688,0.026545053,0.0094940765,0.0320614,-0.04262636,-0.03779201,0.010642199,0.0042657433,-0.065923356,0.011143477,0.041014943,-0.04973496,0.016381558,0.0015325579,0.050869577,0.06310804,-0.025205448,0.02637379,-0.058538456,-0.020318503,0.020464955,0.060040027,0.044397306,-0.04943202,-0.035401333,-0.010008817,-0.0069639077,-0.028675986,0.022264957,0.020922221,0.0035630185,-0.03195762,0.04675859,-0.048435908,0.01320149,-0.017350381,-0.056261115,0.011255137,-0.0011250137,0.016574165,-0.058249287,-0.074259825,-0.0040901164,-0.033222187,-0.0422404,0.006009785,-0.0160031,-0.033824716,-0.008528271,-0.01598322,0.055923276,-0.030256942,0.059412777,0.06612177,-0.038428452,0.030401839,0.019601531,0.033016566,0.009400463,-0.04352333,-0.0046070646,3.9241408E-5,0.056725923,-0.018308273,0.005099161,-0.019018589,-0.025930336,-0.043494012,-0.009985645,0.03387348,-0.0071389265,-0.02443414,-0.031512864,0.047605556,-0.034847748,-0.04141476,-0.116547436,0.0556921,0.05705835,-0.0013922435,0.034026086,-0.0036191102,-0.048820935,-0.030645138,0.0065128934,-0.014017829,-0.02527701,-0.07314901,-0.008973113,-0.016013391,-0.028342836,0.014631479,-0.02325206,-0.0071597607,-0.0025763456,-0.0036126762,0.0010956513,-0.068197966,0.009134159,0.01207908